def followsPatterns(patterns):
    def is_valid(pattern, nums):
        mapping = {}
        for i in range(len(pattern)):
            if pattern[i] not in mapping:
                mapping[pattern[i]] = nums[i]
            elif mapping[pattern[i]] != nums[i]:
                return False
        return True

    for pattern in patterns:
        nums = pattern.split('-')
        if len(nums) != len(set(nums)):
            continue
        for i in range(len(nums)):
            pattern = pattern.replace(str(i), '')
            nums = nums[:i] + nums[i+1:]
            if is_valid(pattern, nums):
                continue
            else:
                return False
    return True

